// THROWAWAY REVISION R: one shared time axis, approximate anchors, mechanical document edits.
// Proposed change from CONTEXT: an explicit user edit updates morning + current plan;
// the initial snapshot and edit history remain separate. No production persistence.
variants.R=['修订候选','统一时间轴 · B 任务结构'];variant='R';
const revisionStart=360,revisionEnd=1440,pxPerMinute=1.2;
const broadPeriods=[['早晨',540],['中午',720],['午后',780],['晚间',1080]];
plans.find(p=>p.id==='p2').anchor=780;
Object.assign(plans.find(p=>p.id==='p3'),{band:'晚间',start:null,end:null,anchor:1080});
plans.push({id:'p5',band:'中午',anchor:720,start:null,end:null,name:'午饭与休息',note:'中午留点时间吃饭、休息。'});
baseline.splice(0,baseline.length,...structuredClone(plans));
const revisionInitialPlans=structuredClone(plans);
const revisionInitialTasks=structuredClone(tasks);
let calendarMarkerPosition='inline';
let planRevisions=[],recordRevision=1,revisionDrag=null,revisionResize=null,revisionPointerDrag=null,suppressPlanClick=false;
const anchorOf=p=>p.start??p.anchor??broadPeriods.find(([label])=>label===p.band)?.[1]??780;
const revisionPlanLabel=p=>p.start==null?(p.band.startsWith('约 ')?p.band:`${p.band} · 约 ${time(anchorOf(p))}`):`${time(p.start)}–${time(p.end)}`;
const broadAt=m=>({band:broadPeriods.find(([,anchor])=>anchor===m)?.[0]??`约 ${time(m)}`,anchor:m,start:null,end:null});
function markdownPlans(items){return items.map(p=>`- ${p.start==null?p.band:time(p.start)+'–'+time(p.end)}｜${p.name}：${p.note}`).join('\n')}
function dailyMarkdown(){return `# Daily Record · 2026-10-10\n\n## 早间计划\n${markdownPlans(baseline)}\n\n## 当前安排\n${markdownPlans(plans)}\n\n## 已记录事实\n${facts.map(f=>`- ${f.time==null?'时刻未记':time(f.time)}｜${f.name}`).join('\n')}\n`}
function commitPlan(id,next,reason){const p=plans.find(p=>p.id===id);if(!p)return;const before=structuredClone(p);if(JSON.stringify(before)===JSON.stringify({...before,...next}))return;planRevisions.push({revision:recordRevision,before,after:{...before,...next},reason});Object.assign(p,next);Object.assign(baseline.find(p=>p.id===id),next);recordRevision++;render();notify('计划时间和两处 Markdown 已同步 · 无模型调用')}
function showMarkdown(){const d=$('#state-dialog');d.innerHTML=`<h2>对应文档 · 示例</h2><p class="help-note">同一条计划的时间同步到早间计划和当前安排。这里只演示内存中的 Markdown，真实文件未写入。</p><pre></pre><details><summary>改动前版本 · ${planRevisions.length} 次修改</summary><pre class="revision-history"></pre></details><button class="btn">关闭</button>`;d.querySelector('pre').textContent=dailyMarkdown();d.querySelector('.revision-history').textContent=JSON.stringify({initialMorningSnapshot:revisionInitialPlans,edits:planRevisions},null,2);d.querySelector('button').onclick=()=>d.close();d.showModal()}
function axisItems(){return [
 ...plans.map(p=>({kind:'plan',id:p.id,start:anchorOf(p),end:p.start==null?anchorOf(p)+60:Math.max(p.end,p.start+45),value:p})),
 ...tasks.filter(t=>t.date==='2026-10-10'&&t.time!=null&&!t.done).map(t=>({kind:'task',id:t.id,start:t.time,end:t.time+Math.max(t.duration,40),value:t})),
 ...facts.filter(f=>f.time!=null).map(f=>({kind:'fact',id:f.id,start:f.time,end:f.time+40,value:f}))
 ].sort((a,b)=>a.start-b.start)}
function assignAxisLanes(items){let group=[],until=-1;const flush=()=>{const ends=[];for(const item of group){let lane=ends.findIndex(end=>end<=item.start);if(lane<0)lane=ends.length;ends[lane]=item.end;item.lane=lane}for(const item of group)item.lanes=ends.length;group=[]};for(const item of items){if(item.start>=until){flush();until=-1}group.push(item);until=Math.max(until,item.end)}flush();return items}
function revisionTimeline(){const items=assignAxisLanes(axisItems());return `<div class="unified-scroll"><div class="unified-axis" data-unified-axis aria-label="统一时间轴：计划、Task 和已记录事实">${Array.from({length:19},(_,i)=>`<span class="unified-tick" style="top:${i*72}px">${i===18?'次日 00:00':time((i+6)*60)}</span>`).join('')}${items.map(item=>{const p=item.value,style=`top:${(item.start-revisionStart)*pxPerMinute}px;left:${item.lane*98/item.lanes}%;width:${98/item.lanes-1}%;height:${item.kind==='plan'&&p.start!=null?(p.end-p.start)*pxPerMinute:(item.end-item.start)*pxPerMinute}px`;if(item.kind==='fact')return `<div class="unified-item fact" style="${style}"><span class="unified-caption">已记录事实 · ${time(p.time)}</span><strong>${esc(p.name)}</strong></div>`;if(item.kind==='task')return `<button class="unified-item task" draggable="false" data-unified-task="${p.id}" data-task="${p.id}" style="${style}"><span class="unified-caption">Task · ${time(p.time)}</span><strong>${esc(p.name)}</strong></button>`;return `<button class="unified-item plan ${p.start==null?'approximate':''}" draggable="false" data-unified-plan="${p.id}" style="${style}"><span class="unified-caption">${p.start==null?'模糊计划 · '+esc(p.band)+' · 大致位置 '+time(anchorOf(p)):'计划 · '+revisionPlanLabel(p)}</span><strong>${esc(p.name)}</strong>${p.start!=null?`<span class="unified-resize" data-unified-resize="${p.id}" title="拖动底边调整结束时间"></span>`:''}</button>`}).join('')}<div class="unified-now" style="top:${(855-revisionStart)*pxPerMinute}px"><span>14:15</span></div><div class="unified-selection hidden"></div><div class="unified-drop" hidden><span></span></div></div></div>`}
function timeSourcePreview(){return `<details class="source-document"><summary>对应文档与改动 · 版本 ${recordRevision}${planRevisions.length?' · '+planRevisions.length+' 次修改':''}</summary><p>拖动或编辑时间，直接同步这两处 Markdown；改动前版本保留。</p><div class="document-sections"><div><h3>早间计划</h3>${baseline.map(p=>`<p>${esc(revisionPlanLabel(p))} · ${esc(p.name)}</p>`).join('')}</div><div><h3>当前安排</h3>${plans.map(p=>`<p>${esc(revisionPlanLabel(p))} · ${esc(p.name)}</p>`).join('')}</div></div><button class="btn" data-document-preview>查看 Markdown</button></details>`}
function revisionMorningText(){return `<section class="surface morning-text"><div class="section-title"><h2>早晨安排</h2><button class="text-button" data-document-preview>查看对应文档</button></div><div class="morning-text-plan">${[...baseline].sort((a,b)=>anchorOf(a)-anchorOf(b)).map(p=>`<section><h3>${esc(p.start==null?p.band:time(p.start)+'–'+time(p.end))} · ${esc(p.name)}</h3><p>${esc(p.note)}</p></section>`).join('')}</div></section>`}
today=()=>{if(phase==='evening')return header('今天','2026 年 10 月 10 日 · 周六')+phaseTabs()+evening();return header('今天','2026 年 10 月 10 日 · 周六',btn('晚间复盘','evening')+btn('与 Codex 讨论','collaboration','primary'))+phaseTabs()+(phase==='morning'?revisionMorningText():`<div class="revision-today-layout"><section class="surface"><div class="section-title"><h2>${phase==='morning'?'早间计划':'时间安排与记录'}</h2><button class="text-button" data-document-preview>查看对应文档</button></div><div class="unified-legend"><span class="plan">□ 当前计划</span><span class="fact">● 已记录事实</span><span class="task">○ Task</span></div><div class="unified-controls"><span>模糊计划显示大致位置；拖动保留时间精度。</span><div>${[['上午',540],['午后',780],['晚间',1080]].map(([label,m])=>`<button class="text-button" data-locate-minute="${m}">${label}</button>`).join('')}</div></div><details class="axis-boundary"><summary>04:00–06:00 · 展开</summary><p>这个示例没有这些时段的安排。</p></details>${revisionTimeline()}<details class="axis-boundary"><summary>次日 00:00–04:00 · 展开</summary><p>这个示例没有这些时段的安排；完整 lived day 保留。</p></details>${timeSourcePreview()}</section>${taskSummary()}</div>`)};
const revisionSelectTask=selectTask;
selectTask=id=>{if(page==='tasks'){selectedTask=id;render()}else revisionSelectTask(id)};
function revisionListRail(){return `<aside class="final-lists"><h2>清单</h2><div class="list-scope">${[['all','全部'],['today','今天'],['inbox','Inbox'],['later','以后想做'],['archived','已归档']].map(([key,label])=>`<button class="btn ${scope===key?'active':''}" data-scope="${key}">${label}</button>`).join('')}</div></aside>`}
taskPage=()=>{const list=filteredTasks(),selected=selectedTask?taskById(selectedTask):null;return header('任务','简洁列表，点击任务查看详情',btn('新任务','new-task','primary'))+`<section class="surface revision-task-layout">${revisionListRail()}<div class="revision-task-list"><div class="section-title"><h2>${scope==='all'?'全部任务':scope==='today'?'今天':scope==='inbox'?'Inbox':scope==='later'?'以后想做':'已归档'}</h2><span class="tiny muted">${list.filter(t=>!t.done).length} 待办</span></div>${quickAdd()}${list.filter(t=>!t.done).map(t=>taskRow(t).replace('class="task-row ',`class="task-row ${t.id===selectedTask?'selected ':''}`)).join('')}${list.some(t=>t.done)?`<details class="completed-list"><summary>已完成 · ${list.filter(t=>t.done).length}</summary>${list.filter(t=>t.done).map(t=>taskRow(t).replace('aria-label="完成 ', 'aria-label="重新打开 ')).join('')}</details>`:''}</div>${selected?taskDetail(selected):'<aside class="detail-panel muted">选择一个任务查看详情</aside>'}</section>`};
const revisedMonth=finalMonth;
// October 2026 occupies five weeks; markers share the date header by default.
finalMonth=()=>{const html=revisedMonth(),buttons=html.match(/<button class="calendar-day[\s\S]*?<\/button>/g);return html.slice(0,html.indexOf('<div class="calendar-grid">'))+`<div class="calendar-grid marker-${calendarMarkerPosition}">`+buttons.slice(0,35).map(button=>{const marker=button.match(/<span class="calendar-day-marker [^"]*" aria-hidden="true">[^<]*<\/span>/)?.[0]||'',more=button.match(/<span class="calendar-more">[^<]*<\/span>/)?.[0]||'';button=button.replace(more,'');if(calendarMarkerPosition==='inline')button=button.replace(marker,'').replace('</strong>','</strong>'+marker);return button.replace('</strong>','</strong>'+more)}).join('')+'</div>'};
const revisionCalendarPage=calendarPage;
calendarPage=()=>{let html=revisionCalendarPage();for(const p of plans)html=html.replaceAll(planLabel(p),revisionPlanLabel(p));html=html.replace('<div class="section-title"><h2>2026 年 10 月</h2></div><div class="calendar-legend">','<div class="compact-month-heading"><h2>2026 年 10 月</h2><div class="calendar-legend">').replace(/(<div class="calendar-legend">[\s\S]*?<\/div>)/,'$1</div>');return html.replace('<div class="head-actions">',`<div class="head-actions"><div class="calendar-marker-options" role="group" aria-label="复盘标记位置"><span>复盘标记</span><button class="text-button" data-marker-position="inline" aria-pressed="${calendarMarkerPosition==='inline'}">日期旁</button><button class="text-button" data-marker-position="corner" aria-pressed="${calendarMarkerPosition==='corner'}">右下角</button></div>`)};
function openRevisionPlanEditor(p){const d=$('#detail-dialog'),known=broadPeriods.find(([label])=>label===p.band);d.innerHTML=`<h2>调整计划时间</h2><p><b>${esc(p.name)}</b></p><form id="revision-plan-form"><label for="revision-precision">时间精度</label><select id="revision-precision"><option value="exact" ${p.start!=null?'selected':''}>具体起止时间</option><option value="broad" ${p.start==null?'selected':''}>模糊时间</option></select><div id="revision-exact-fields" class="plan-edit-grid" ${p.start==null?'hidden':''}><div><label for="revision-start">开始</label><input id="revision-start" type="time" value="${time(anchorOf(p))}"></div><div><label for="revision-end">结束</label><input id="revision-end" type="time" value="${time(p.end??anchorOf(p)+60)}"></div></div><div id="revision-broad-fields" ${p.start!=null?'hidden':''}><label for="revision-period">大致时段</label><select id="revision-period">${broadPeriods.map(([label])=>`<option ${p.band===label?'selected':''}>${label}</option>`).join('')}<option ${!known?'selected':''}>自定义大致时间</option></select><div id="revision-anchor-field" ${known?'hidden':''}><label for="revision-anchor">大致时间</label><input id="revision-anchor" type="time" value="${time(anchorOf(p))}"></div></div><p class="plan-edit-note">采用后直接同步早间计划与当前安排的 Markdown 时间字段，保留改动前版本。</p><div class="inline-actions"><button type="button" class="btn" id="revision-cancel">取消</button><button class="btn primary">采用这个安排</button></div></form>`;d.showModal();$('#revision-cancel').onclick=()=>d.close();$('#revision-precision').onchange=e=>{$('#revision-exact-fields').hidden=e.target.value!=='exact';$('#revision-broad-fields').hidden=e.target.value==='exact'};$('#revision-period').onchange=e=>$('#revision-anchor-field').hidden=e.target.value!=='自定义大致时间';$('#revision-plan-form').onsubmit=e=>{e.preventDefault();const minute=v=>v?+v.slice(0,2)*60+(+v.slice(3)):null;let next;if($('#revision-precision').value==='exact'){const a=minute($('#revision-start').value),b=minute($('#revision-end').value);if(a==null||b==null||b<=a||a<revisionStart||b>revisionEnd){notify('请选择 06:00–24:00 示例窗口内的有效起止时间');return}next={start:a,end:b,anchor:a,band:bandOf(a)}}else{const label=$('#revision-period').value,anchor=broadPeriods.find(([b])=>b===label)?.[1]??minute($('#revision-anchor').value);if(anchor==null||anchor<revisionStart||anchor>=revisionEnd){notify('请选择有效的大致时间');return}next={...broadAt(anchor),band:label==='自定义大致时间'?`约 ${time(anchor)}`:label}}d.close();commitPlan(p.id,next,'编辑计划时间')}}
function applyUnifiedDrag(drag,m){if(drag.kind==='task'){const t=taskById(drag.id);t.time=Math.max(revisionStart,Math.min(revisionEnd-t.duration,m));t.date='2026-10-10';render();notify('Task 时间已更新')}else{const p=plans.find(p=>p.id===drag.id);if(p.start==null)commitPlan(p.id,broadAt(Math.max(revisionStart,Math.min(revisionEnd-60,m))),'拖动模糊计划');else{const duration=p.end-p.start,start=Math.max(revisionStart,Math.min(revisionEnd-duration,m));commitPlan(p.id,{start,end:start+duration,band:bandOf(start),anchor:start},'拖动具体计划')}}}
function bindUnifiedTimeline(){const axis=$('[data-unified-axis]');if(!axis)return;const scroller=axis.closest('.unified-scroll'),minute=y=>Math.max(revisionStart,Math.min(revisionEnd-15,Math.round((y-axis.getBoundingClientRect().top)/pxPerMinute/15)*15+revisionStart)),drop=axis.querySelector('.unified-drop');
 axis.onpointerdown=e=>{const handle=e.target.closest('[data-unified-resize]');if(handle){e.preventDefault();const p=plans.find(p=>p.id===handle.dataset.unifiedResize);revisionResize={p,element:handle.closest('[data-unified-plan]'),end:p.end};axis.setPointerCapture(e.pointerId);return}const item=e.target.closest('[data-unified-plan],[data-unified-task]');if(item){e.preventDefault();revisionPointerDrag={kind:item.dataset.unifiedPlan?'plan':'task',id:item.dataset.unifiedPlan||item.dataset.unifiedTask,offset:Math.round((e.clientY-item.getBoundingClientRect().top)/pxPerMinute/15)*15,initialY:e.clientY,moved:false};axis.setPointerCapture(e.pointerId);return}if(e.target.closest('.unified-item'))return;selection={axis,start:minute(e.clientY),end:minute(e.clientY)};axis.setPointerCapture(e.pointerId);axis.querySelector('.unified-selection').classList.remove('hidden')};
 axis.onpointermove=e=>{if(revisionPointerDrag){if(Math.abs(e.clientY-revisionPointerDrag.initialY)>5)revisionPointerDrag.moved=true;if(revisionPointerDrag.moved){autoScroll(scroller,e.clientY);const m=Math.max(revisionStart,minute(e.clientY)-revisionPointerDrag.offset);drop.hidden=false;drop.style.top=(m-revisionStart)*pxPerMinute+'px';drop.querySelector('span').textContent=time(m)}return}if(revisionResize){autoScroll(scroller,e.clientY);revisionResize.end=Math.max(revisionResize.p.start+15,Math.min(revisionEnd,minute(e.clientY)));revisionResize.element.style.height=(revisionResize.end-revisionResize.p.start)*pxPerMinute+'px';revisionResize.element.querySelector('.unified-caption').textContent=`计划 · ${time(revisionResize.p.start)}–${time(revisionResize.end)}`;return}if(!selection)return;autoScroll(scroller,e.clientY);selection.end=minute(e.clientY);const ghost=axis.querySelector('.unified-selection');ghost.style.top=(Math.min(selection.start,selection.end)-revisionStart)*pxPerMinute+'px';ghost.style.height=Math.max(18,Math.abs(selection.end-selection.start)*pxPerMinute)+'px'};
 axis.onpointerup=e=>{stopScroll();if(revisionPointerDrag){const drag=revisionPointerDrag;revisionPointerDrag=null;drop.hidden=true;if(drag.moved){suppressPlanClick=true;setTimeout(()=>suppressPlanClick=false,0);applyUnifiedDrag(drag,minute(e.clientY)-drag.offset)}else if(drag.kind==='plan')openRevisionPlanEditor(plans.find(p=>p.id===drag.id));else selectTask(drag.id);return}if(revisionResize){const r=revisionResize;revisionResize=null;commitPlan(r.p.id,{end:r.end},'调整计划结束时间');return}if(!selection)return;const start=Math.min(selection.start,selection.end),end=Math.max(selection.start,selection.end);selection=null;axis.querySelector('.unified-selection').classList.add('hidden');if(end-start>=15)openTaskDialog(null,start,end)};
 axis.onpointercancel=()=>{stopScroll();revisionPointerDrag=null;revisionResize=null;selection=null;render()};
}
const revisionBind=bind;
bind=()=>{revisionBind();bindUnifiedTimeline();document.querySelectorAll('[data-marker-position]').forEach(el=>el.onclick=()=>{calendarMarkerPosition=el.dataset.markerPosition;render()});document.querySelectorAll('[data-unified-plan]').forEach(el=>el.onclick=()=>{if(suppressPlanClick){suppressPlanClick=false;return}if(!$('#detail-dialog').open)openRevisionPlanEditor(plans.find(p=>p.id===el.dataset.unifiedPlan))});document.querySelectorAll('[data-document-preview]').forEach(el=>el.onclick=showMarkdown);document.querySelectorAll('[data-locate-minute]').forEach(el=>el.onclick=()=>{const scroller=$('.unified-scroll');scroller.scrollTop=(+el.dataset.locateMinute-revisionStart)*pxPerMinute-90})};
const revisionRender=render;
render=()=>{const scrollTop=$('.unified-scroll')?.scrollTop;revisionRender();$('#variant-name').textContent='修订候选 · 等你过目';if(page==='today'&&phase==='daytime')$('.unified-scroll').scrollTop=scrollTop??((480-revisionStart)*pxPerMinute-12)};
$('#reset').onclick=()=>{stopScroll();tasks=structuredClone(revisionInitialTasks);plans=structuredClone(revisionInitialPlans);baseline.splice(0,baseline.length,...structuredClone(plans));planRevisions=[];recordRevision=1;selectedTask='t2';scope='all';draft='';lastAction='已还原示例';render();notify(lastAction)};
$('#inspect').onclick=showMarkdown;
if(messages[1])messages[1].text='计划可以有具体时间或模糊时间；拖动会同步文档中对应计划的时间字段。';
render();
